/* Flashcards app — vanilla JS, no build step.
 * Data: cards.json (generated by tools/import_doc.py) = { decks: [ { key, title, sections: [ { name, cards } ] } ] }
 * Progress: localStorage (nf.v1), in-progress session: localStorage (nf.session.v1)
 */
(() => {
  'use strict';

  const STORE_KEY = 'nf.v1';
  const SESSION_KEY = 'nf.session.v1';
  const PREFS_KEY = 'nf.prefs.v2';

  const $app = document.getElementById('app');
  const $nav = document.getElementById('nav');
  const $toast = document.getElementById('toast');

  const state = {
    decks: [],
    cards: new Map(),        // id -> card (+ section, deckKey)
    progress: loadJSON(STORE_KEY) || { cards: {}, sessions: [] },
    session: loadJSON(SESSION_KEY) || null,
    prefs: loadJSON(PREFS_KEY) || { deck: null, sectionsByDeck: {}, order: 'ordered', scope: 'all', mode: 'rounds' },
    view: 'home',
    browseQuery: '',
  };

  // ------------------------------------------------------------ utilities
  function loadJSON(k) { try { return JSON.parse(localStorage.getItem(k)); } catch { return null; } }
  function saveJSON(k, v) { try { if (v == null) localStorage.removeItem(k); else localStorage.setItem(k, JSON.stringify(v)); } catch (e) { toast('Could not save (storage full?)'); } }
  function saveProgress() { saveJSON(STORE_KEY, state.progress); }
  function saveSession() { saveJSON(SESSION_KEY, state.session); }
  function savePrefs() { saveJSON(PREFS_KEY, state.prefs); }
  function esc(s) { return String(s ?? '').replace(/[&<>"']/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c])); }
  function h(strings, ...vals) { return strings.reduce((out, s, i) => out + s + (i < vals.length ? vals[i] : ''), ''); }
  function shuffle(a) { const r = a.slice(); for (let i = r.length - 1; i > 0; i--) { const j = Math.floor(Math.random() * (i + 1)); [r[i], r[j]] = [r[j], r[i]]; } return r; }
  function pct(n, d) { return d ? Math.round(100 * n / d) : 0; }
  function fmtDate(ts) { const d = new Date(ts); return d.toLocaleDateString(undefined, { month: 'short', day: 'numeric' }) + ' ' + d.toLocaleTimeString(undefined, { hour: 'numeric', minute: '2-digit' }); }
  let toastTimer;
  function toast(msg) { $toast.textContent = msg; $toast.classList.add('show'); clearTimeout(toastTimer); toastTimer = setTimeout(() => $toast.classList.remove('show'), 2200); }

  function rec(id) { return state.progress.cards[id] || null; }
  function statusOf(id) { const r = rec(id); return r ? r.status : null; }
  function isMastered(id) { return statusOf(id) === 'yes'; }

  // ------------------------------------------------------------ deck loading
  async function loadDecks() {
    const res = await fetch('cards.json', { cache: 'no-cache' });
    if (!res.ok) throw new Error('cards.json ' + res.status);
    const data = await res.json();
    state.decks = data.decks || [{ key: 'single', title: data.title || 'Flashcards', generatedAt: data.generatedAt, cardCount: data.cardCount, sections: data.sections }];
    state.cards.clear();
    for (const d of state.decks) for (const s of d.sections) for (const c of s.cards) state.cards.set(c.id, { ...c, section: s.name, sectionKey: sKey(s), sectionLabel: sLabel(d, s), group: s.group || '', deckKey: d.key, deckTitle: d.title });
    if (!state.decks.some(d => d.key === state.prefs.deck)) state.prefs.deck = state.decks[0].key;
    for (const d of state.decks) {
      const names = d.sections.map(sKey);
      const sel = state.prefs.sectionsByDeck[d.key];
      state.prefs.sectionsByDeck[d.key] = sel && sel.some(n => names.includes(n)) ? sel.filter(n => names.includes(n)) : names.slice();
    }
    document.title = state.decks.length === 1 ? state.decks[0].title : 'Flashcards';
    if (state.session && state.session.queue.some(id => !state.cards.has(id))) { state.session = null; saveSession(); }
  }
  function deck() { return state.decks.find(d => d.key === state.prefs.deck) || state.decks[0]; }
  function sKey(sec) { return sec.group ? sec.group + '\u241f' + sec.name : sec.name; }
  function sLabel(d, sec) { return sec.group && sec.name === sec.group && d.sections.some(x => x !== sec && x.group === sec.group) ? 'General' : sec.name; }
  function groupsOf(d) {
    const out = [];
    for (const sec of d.sections) { const g = sec.group || ''; let G = out.find(x => x.name === g); if (!G) out.push(G = { name: g, secs: [] }); G.secs.push(sec); }
    return out;
  }
  function selectedSections() { return state.prefs.sectionsByDeck[deck().key]; }

  // ------------------------------------------------------------ selection
  function selectCards(cfg) {
    const d = state.decks.find(x => x.key === cfg.deck) || deck();
    const secs = new Set(cfg.sections);
    let groups = d.sections.filter(s => secs.has(sKey(s))).map(s => s.cards.map(c => c.id));
    if (cfg.scope === 'unmastered') groups = groups.map(g => g.filter(id => !isMastered(id)));
    if (cfg.scope === 'weakest') groups = [weakestIds(groups.flat(), 20)];
    if (cfg.order === 'section') groups = groups.map(shuffle);
    let ids = groups.flat();
    if (cfg.order === 'shuffled') ids = shuffle(ids);
    return ids;
  }
  function weakestIds(pool, n) {
    const scored = pool.map(id => { const r = rec(id) || { yes: 0, no: 0, last: 0, status: null }; return { id, k: [r.no, r.status === 'no' ? 1 : 0, -r.yes, r.last] }; })
      .filter(x => x.k[0] > 0 || x.k[1] > 0);
    scored.sort((a, b) => b.k[0] - a.k[0] || b.k[1] - a.k[1] || b.k[2] - a.k[2] || b.k[3] - a.k[3]);
    return scored.slice(0, n).map(x => x.id);
  }
  function countFor(cfg) { return selectCards({ ...cfg, order: 'ordered' }).length; }
  function homeCfg() { const p = state.prefs; return { deck: deck().key, sections: selectedSections().slice(), order: p.order, scope: p.scope, mode: p.mode }; }

  // ------------------------------------------------------------ session engine
  function startSession(cfg) {
    const queue = selectCards(cfg);
    if (!queue.length) { toast('No cards match that selection'); return; }
    state.session = {
      config: cfg, queue, index: 0, round: 1, flipped: false,
      answers: [], roundYes: [], roundNo: [], seen: [], firstYes: 0, firstNo: 0,
      startedAt: Date.now(),
    };
    saveSession();
    go('study');
  }
  function currentId() { const s = state.session; return s && s.index < s.queue.length ? s.queue[s.index] : null; }

  function answer(yes) {
    const s = state.session; const id = currentId(); if (!s || !id || !s.flipped) return;
    const prev = rec(id) ? { ...rec(id) } : null;
    const r = prev ? { ...prev } : { status: null, yes: 0, no: 0, last: 0 };
    r.status = yes ? 'yes' : 'no'; r[yes ? 'yes' : 'no'] += 1; r.last = Date.now();
    state.progress.cards[id] = r;
    if (!s.seen.includes(id)) { s.seen.push(id); if (yes) s.firstYes++; else s.firstNo++; }
    const entry = { id, yes, round: s.round, prev, reinserted: null };
    (yes ? s.roundYes : s.roundNo).push(id);
    if (!yes && s.config.mode === 'reinsert') {
      const gap = 4 + Math.floor(Math.random() * 5);
      const pos = Math.min(s.queue.length, s.index + 1 + gap);
      s.queue.splice(pos, 0, id);
      entry.reinserted = pos;
    }
    s.answers.push(entry);
    s.index++; s.flipped = false;
    Cheer.onAnswer(yes);
    saveProgress();
    if (s.index >= s.queue.length) { s.phase = 'summary'; saveSession(); render(); return; }
    saveSession(); render();
  }
  function undo() {
    const s = state.session; if (!s || !s.answers.length) return;
    const e = s.answers.pop();
    if (e.prev) state.progress.cards[e.id] = e.prev; else delete state.progress.cards[e.id];
    if (e.reinserted != null) s.queue.splice(e.reinserted, 1);
    const pile = e.yes ? s.roundYes : s.roundNo; const i = pile.lastIndexOf(e.id); if (i >= 0) pile.splice(i, 1);
    if (!s.answers.some(a => a.id === e.id)) { const k = s.seen.indexOf(e.id); if (k >= 0) s.seen.splice(k, 1); if (e.yes) s.firstYes--; else s.firstNo--; }
    s.index--; s.flipped = true; s.phase = null;
    saveProgress(); saveSession(); render();
  }
  function nextRound() {
    const s = state.session;
    let q = s.roundNo.slice();
    if (s.config.order !== 'ordered') q = shuffle(q);
    s.queue = q; s.index = 0; s.round++; s.roundYes = []; s.roundNo = []; s.flipped = false; s.phase = null;
    saveSession(); render();
  }
  function endSession(record = true) {
    const s = state.session; if (!s) return;
    if (record && s.seen.length) {
      const d = state.decks.find(x => x.key === s.config.deck);
      state.progress.sessions.push({
        at: s.startedAt, deck: d ? d.title : '', sections: s.config.sections, mode: s.config.mode, order: s.config.order, scope: s.config.scope,
        cards: s.seen.length, yes: s.firstYes, no: s.firstNo, rounds: s.round, secs: Math.round((Date.now() - s.startedAt) / 1000),
      });
      if (state.progress.sessions.length > 200) state.progress.sessions.splice(0, state.progress.sessions.length - 200);
      saveProgress();
    }
    state.session = null; saveSession();
  }

  // ------------------------------------------------------------ stats helpers
  function sectionStats(sec) {
    let y = 0, n = 0, u = 0;
    for (const c of sec.cards) { const st = statusOf(c.id); if (st === 'yes') y++; else if (st === 'no') n++; else u++; }
    return { y, n, u, t: sec.cards.length };
  }
  function deckStats(d) {
    let y = 0, n = 0, u = 0, t = 0;
    for (const s of d.sections) { const r = sectionStats(s); y += r.y; n += r.n; u += r.u; t += r.t; }
    return { y, n, u, t };
  }
  function barHtml(st, tall) {
    return h`<div class="bar${tall ? ' tall' : ''}"><div class="y" style="width:${pct(st.y, st.t)}%"></div><div class="n" style="width:${pct(st.n, st.t)}%"></div></div>`;
  }
  function deckPicker() {
    if (state.decks.length < 2) return '';
    return h`<div class="field" style="margin-top:0"><label class="lbl">Test</label><div class="chips">${state.decks.map(d => { const s = deckStats(d); return h`<button class="chip ${d.key === deck().key ? 'on' : ''}" data-deck="${esc(d.key)}">${esc(d.title)} <span class="cnt">${s.y}/${s.t}</span></button>`; }).join('')}</div></div>`;
  }
  function bindDeckPicker(rerender) {
    $app.querySelectorAll('[data-deck]').forEach(b => b.onclick = () => { state.prefs.deck = b.dataset.deck; savePrefs(); rerender(); });
  }

  // ------------------------------------------------------------ routing
  function go(view) { state.view = view; location.hash = view === 'home' ? '' : view; render(); }
  window.addEventListener('hashchange', () => {
    const v = (location.hash || '#home').slice(1).split('=')[0] || 'home';
    if (v === 'sync' && location.hash.startsWith('#sync=')) { handleIncomingSync(location.hash.slice(6)); return; }
    if (v === 'study' && !state.session) { state.view = 'home'; render(); return; }
    state.view = ['home', 'study', 'stats', 'browse', 'sync'].includes(v) ? v : 'home'; render();
  });

  // ------------------------------------------------------------ render
  function render() {
    document.body.classList.toggle('studying', state.view === 'study');
    for (const a of $nav.querySelectorAll('a')) a.classList.toggle('active', a.dataset.view === state.view);
    window.scrollTo(0, 0);
    switch (state.view) {
      case 'study': return state.session && state.session.phase === 'summary' ? renderSummary() : renderStudy();
      case 'stats': return renderStats();
      case 'browse': return renderBrowse();
      case 'sync': return renderSync();
      default: return renderHome();
    }
  }

  // ---- home
  function renderHome() {
    const d = deck(); const p = state.prefs; const st = deckStats(d);
    const cfg = homeCfg();
    const count = countFor(cfg);
    const resume = state.session;
    const sel = selectedSections();
    const orderHint = { ordered: 'Cards come in the order they appear in the doc.', section: 'Sections stay in order; cards are shuffled inside each section.', shuffled: 'Everything mixed together.' }[p.order];
    $app.innerHTML = h`
      <h1>${esc(d.title)}</h1>
      <p class="sub">${d.cardCount} cards · ${d.sections.length} sections · mastered ${st.y}/${st.t} (${pct(st.y, st.t)}%)</p>
      ${barHtml(st, true)}
      <div class="legend"><span class="ly"><i></i>Got it ${st.y}</span><span class="ln"><i></i>Still learning ${st.n}</span><span class="lu"><i></i>Not seen ${st.u}</span></div>

      ${resume ? h`<div class="panel" style="margin-top:16px">
          <div class="row"><div><b>Session in progress</b><div class="hint">${esc(state.cards.get(resume.queue[0])?.deckTitle || '')} · Round ${resume.round} · card ${Math.min(resume.index + 1, resume.queue.length)} of ${resume.queue.length}</div></div>
          <div class="spacer"></div><button class="btn primary" data-act="resume">Continue</button><button class="btn" data-act="discard">Discard</button></div></div>` : ''}

      <div class="panel" style="margin-top:16px">
        ${deckPicker()}
        <div class="field"><label class="lbl">Sections <span class="hint" style="display:inline;text-transform:none;letter-spacing:0;font-weight:500">· <button class="link" data-act="all">All</button> · <button class="link" data-act="none">None</button></span></label>
          ${groupsOf(d).map(G => h`<div class="grp">${G.name ? h`<button class="grp-name" data-grp="${esc(G.name)}" title="Toggle all in ${esc(G.name)}">${esc(G.name)}</button>` : ''}
            <div class="chips">${G.secs.map(sec => { const ss = sectionStats(sec); const k = sKey(sec); return h`<button class="chip ${sel.includes(k) ? 'on' : ''}" data-sec="${esc(k)}">${esc(sLabel(d, sec))} <span class="cnt">${ss.y}/${ss.t}</span></button>`; }).join('')}</div></div>`).join('')}
        </div>
        <div class="field"><label class="lbl">Which cards</label>
          <div class="seg" data-pref="scope">
            <button class="${p.scope === 'all' ? 'on' : ''}" data-val="all">All</button>
            <button class="${p.scope === 'unmastered' ? 'on' : ''}" data-val="unmastered">Not yet mastered</button>
            <button class="${p.scope === 'weakest' ? 'on' : ''}" data-val="weakest">Weakest 20</button>
          </div></div>
        <div class="field"><label class="lbl">Order</label>
          <div class="seg" data-pref="order">
            <button class="${p.order === 'ordered' ? 'on' : ''}" data-val="ordered">In order</button>
            <button class="${p.order === 'section' ? 'on' : ''}" data-val="section">Shuffle within section</button>
            <button class="${p.order === 'shuffled' ? 'on' : ''}" data-val="shuffled">Shuffle all</button>
          </div><div class="hint">${orderHint}</div></div>
        <div class="field"><label class="lbl">When I miss a card</label>
          <div class="seg" data-pref="mode">
            <button class="${p.mode === 'rounds' ? 'on' : ''}" data-val="rounds">Rounds</button>
            <button class="${p.mode === 'reinsert' ? 'on' : ''}" data-val="reinsert">Bring it back soon</button>
          </div>
          <div class="hint">${p.mode === 'rounds' ? 'Finish the deck, then repeat only the missed cards, round after round, until none are left.' : 'A missed card comes back 4–8 cards later in the same pass. The session ends when every card has been answered "Got it".'}</div>
        </div>
        <button class="btn primary big" data-act="start" ${count ? '' : 'disabled'}>Study ${count} card${count === 1 ? '' : 's'}</button>
      </div>
      ${Cheer.pillHtml()}
      <p class="hint kbd-only">Keyboard: <span class="kbd">Space</span> flip · <span class="kbd">→</span> or <span class="kbd">Y</span> got it · <span class="kbd">←</span> or <span class="kbd">N</span> still learning · <span class="kbd">U</span> undo</p>
      <p class="hint">Deck updated ${d.generatedAt ? fmtDate(d.generatedAt) : '—'}</p>`;

    bindDeckPicker(renderHome);
    Cheer.bind($app);
    $app.querySelectorAll('.chip[data-sec]').forEach(b => b.onclick = () => {
      const n = b.dataset.sec; const i = sel.indexOf(n);
      if (i >= 0) sel.splice(i, 1); else sel.push(n);
      savePrefs(); renderHome();
    });
    $app.querySelectorAll('.seg[data-pref] button').forEach(b => b.onclick = () => { p[b.parentElement.dataset.pref] = b.dataset.val; savePrefs(); renderHome(); });
    $app.querySelectorAll('[data-grp]').forEach(b => b.onclick = () => {
      const keys = d.sections.filter(sec => (sec.group || '') === b.dataset.grp).map(sKey);
      const allOn = keys.every(k => sel.includes(k));
      p.sectionsByDeck[d.key] = allOn ? sel.filter(k => !keys.includes(k)) : [...new Set([...sel, ...keys])];
      savePrefs(); renderHome();
    });
    $app.querySelector('[data-act=all]').onclick = () => { p.sectionsByDeck[d.key] = d.sections.map(sKey); savePrefs(); renderHome(); };
    $app.querySelector('[data-act=none]').onclick = () => { p.sectionsByDeck[d.key] = []; savePrefs(); renderHome(); };
    $app.querySelector('[data-act=start]').onclick = () => { if (state.session) endSession(true); startSession(homeCfg()); };
    const r = $app.querySelector('[data-act=resume]'); if (r) r.onclick = () => go('study');
    const dsc = $app.querySelector('[data-act=discard]'); if (dsc) dsc.onclick = () => { if (confirm('Discard the in-progress session? Answers already given are kept in your stats.')) { endSession(true); renderHome(); } };
  }

  // ---- study
  let touch = null;
  function renderStudy() {
    const s = state.session; const id = currentId();
    if (!s || !id) { state.view = 'home'; return renderHome(); }
    const c = state.cards.get(id);
    const total = s.queue.length; const done = s.index;
    const remaining = s.config.mode === 'reinsert' ? new Set(s.queue.slice(s.index)).size : total - done;
    const kicker = [c.group, c.sectionLabel !== c.group || !c.group ? c.sectionLabel : '', c.label].filter(Boolean).map(esc).join(' · ');
    $app.innerHTML = h`
      <div class="study">
        <div class="study-top">
          <button class="btn small" data-act="end">End</button>
          <div class="prog"><div class="txt"><span>${s.config.mode === 'rounds' ? `Round ${s.round} · ` : ''}${done + 1} / ${total}</span><span>${remaining} left</span></div>
            <div class="bar"><div class="p" style="width:${pct(done, total)}%"></div></div></div>
          <button class="btn small" data-act="undo" ${s.answers.length ? '' : 'disabled'}>Undo</button>
        </div>
        <div class="card ${s.flipped ? 'is-back' : ''} ${c.imagePrompt ? 'img-prompt' : ''}" id="card" tabindex="0" role="button" aria-label="${s.flipped ? 'Answer' : 'Prompt, tap to reveal answer'}">
          <div class="kicker"><span>${kicker}</span><span>${state.decks.length > 1 ? esc(c.deckTitle) : ''}</span></div>
          ${s.flipped
            ? h`<div class="back"><div class="q">${c.promptHtml || esc(c.prompt)}</div><div class="a">${c.answerHtml || '<i>(no answer)</i>'}</div></div>`
            : h`<div class="front"><div class="prompt">${c.promptHtml || esc(c.prompt)}</div></div><div class="tap-hint">Tap to reveal</div>`}
        </div>
        <div class="actions">
          ${s.flipped
            ? h`<button class="btn no" data-act="no">Still learning<span class="k kbd-only">← or N</span></button><button class="btn yes" data-act="yes">Got it<span class="k kbd-only">→ or Y</span></button>`
            : h`<button class="btn primary single" data-act="flip">Show answer<span class="k kbd-only">Space</span></button>`}
        </div>
        <div class="under"><span>${s.roundYes.length} got it · ${s.roundNo.length} still learning</span>${Cheer.current()
          ? h`<span class="cheer-nudge"><button class="cheer-pill" data-act="cheer">${esc(Cheer.current())}</button><button class="cheer-x" data-act="cheer-dismiss" aria-label="Dismiss">×</button></span>`
          : h`<span>${s.flipped ? 'Swipe → got it · ← still learning' : ''}</span>`}</div>
      </div>`;

    const $card = $app.querySelector('#card');
    const flip = () => { if (s.flipped) return; $card.classList.add('flipping'); setTimeout(() => { s.flipped = true; saveSession(); renderStudy(); }, 150); };
    $card.addEventListener('click', (e) => {
      if (e.target.closest('a')) return;
      if (!s.flipped) { flip(); return; }
      const img = e.target.closest('img'); if (img) openLightbox(img.src);
    });
    const f = $app.querySelector('[data-act=flip]'); if (f) f.onclick = flip;
    const y = $app.querySelector('[data-act=yes]'); if (y) y.onclick = () => answer(true);
    const n = $app.querySelector('[data-act=no]'); if (n) n.onclick = () => answer(false);
    $app.querySelector('[data-act=undo]').onclick = undo;
    Cheer.bind($app);
    $app.querySelector('[data-act=end]').onclick = () => { if (confirm('End this session? Your answers so far are saved.')) { endSession(true); go('home'); } };

    // swipe (only when flipped)
    $card.addEventListener('touchstart', (e) => { if (!s.flipped || e.touches.length !== 1) return; touch = { x: e.touches[0].clientX, y: e.touches[0].clientY }; }, { passive: true });
    $card.addEventListener('touchmove', (e) => {
      if (!touch) return; const dx = e.touches[0].clientX - touch.x, dy = e.touches[0].clientY - touch.y;
      if (Math.abs(dx) > 12 && Math.abs(dx) > Math.abs(dy) * 1.3) { $card.classList.add('dragging'); $card.style.transform = `translateX(${dx * 0.6}px) rotate(${dx / 40}deg)`; }
    }, { passive: true });
    $card.addEventListener('touchend', (e) => {
      if (!touch) return; const dx = e.changedTouches[0].clientX - touch.x, dy = e.changedTouches[0].clientY - touch.y; touch = null;
      $card.classList.remove('dragging'); $card.style.transform = '';
      if (Math.abs(dx) > 70 && Math.abs(dx) > Math.abs(dy) * 1.3) answer(dx > 0);
    }, { passive: true });
    $card.addEventListener('touchcancel', () => { touch = null; $card.classList.remove('dragging'); $card.style.transform = ''; }, { passive: true });
  }

  document.addEventListener('keydown', (e) => {
    if (e.key === 'Escape') { closeLightbox(); Cheer.close(); return; }
    if (state.view !== 'study' || !state.session) return;
    if (e.target && ['INPUT', 'TEXTAREA'].includes(e.target.tagName)) return;
    const s = state.session; const k = e.key;
    if (s.phase === 'summary') { if (k === 'Enter' || k === ' ') { e.preventDefault(); const b = $app.querySelector('[data-act=next]') || $app.querySelector('[data-act=finish]'); b && b.click(); } return; }
    if (k === ' ' || k === 'Enter') { e.preventDefault(); if (!s.flipped) { s.flipped = true; saveSession(); renderStudy(); } return; }
    if (k === 'ArrowRight' || k === 'y' || k === 'Y') { e.preventDefault(); answer(true); }
    else if (k === 'ArrowLeft' || k === 'n' || k === 'N') { e.preventDefault(); answer(false); }
    else if (k === 'u' || k === 'U' || k === 'Backspace') { e.preventDefault(); undo(); }
  });

  // ---- lightbox
  function openLightbox(src) {
    closeLightbox();
    const el = document.createElement('div'); el.className = 'lightbox'; el.id = 'lightbox';
    el.innerHTML = `<img src="${esc(src)}" alt=""><div class="lb-hint">Tap to close</div>`;
    el.onclick = closeLightbox;
    document.body.appendChild(el);
  }
  function closeLightbox() { const el = document.getElementById('lightbox'); if (el) el.remove(); }

  // ---- summary
  function renderSummary() {
    const s = state.session; const rounds = s.config.mode === 'rounds';
    const missed = s.roundNo; const got = s.roundYes;
    const doneAll = missed.length === 0;
    $app.innerHTML = h`
      <div class="study"><div class="summary">
        <p class="sub">${rounds ? `Round ${s.round} complete` : 'Session complete'}</p>
        <div class="big" style="color:${doneAll ? 'var(--yes)' : 'var(--ink)'}">${doneAll ? '🎉' : pct(got.length, got.length + missed.length) + '%'}</div>
        <h1 style="margin-top:0">${doneAll ? (rounds && s.round > 1 ? 'Every card mastered!' : 'All cards got it!') : `${got.length} got it · ${missed.length} still learning`}</h1>
        ${rounds && !doneAll ? h`<p class="sub">Round ${s.round + 1} will have ${missed.length} card${missed.length === 1 ? '' : 's'}.</p>` : ''}
        ${!rounds ? h`<p class="sub">First pass: ${s.firstYes} of ${s.seen.length} right away.</p>` : ''}
        <div class="row" style="justify-content:center; margin-top:16px">
          ${rounds && !doneAll ? h`<button class="btn primary big" data-act="next">Start round ${s.round + 1}</button>` : ''}
          <button class="btn ${rounds && !doneAll ? '' : 'primary'} big" data-act="finish">Finish</button>
        </div>
        ${Cheer.pillHtml()}
        ${missed.length ? h`<div class="panel pile" style="margin-top:20px"><b>Still learning</b><ul class="list">${missed.map(id => h`<li><span class="dot no"></span>${esc(state.cards.get(id).prompt)}</li>`).join('')}</ul></div>` : ''}
      </div></div>`;
    const nx = $app.querySelector('[data-act=next]'); if (nx) nx.onclick = nextRound;
    Cheer.bind($app);
    $app.querySelector('[data-act=finish]').onclick = () => { endSession(true); go('stats'); };
  }

  // ---- stats
  function renderStats() {
    const d = deck(); const st = deckStats(d);
    const weakest = weakestIds(d.sections.flatMap(s => s.cards.map(c => c.id)), 15);
    const sessions = state.progress.sessions.slice().reverse().filter(x => !x.deck || x.deck === d.title).slice(0, 12);
    $app.innerHTML = h`
      <h1>Stats</h1>
      ${state.decks.length > 1 ? h`<div class="panel">${deckPicker()}</div>` : ''}
      <div class="stat-grid">
        <div class="stat y"><b>${st.y}</b><span>got it</span></div>
        <div class="stat n"><b>${st.n}</b><span>still learning</span></div>
        <div class="stat"><b>${st.u}</b><span>not seen</span></div>
      </div>
      <div class="panel" style="margin-top:14px">
        <div class="row"><b>${esc(d.title)} mastery</b><div class="spacer"></div><span>${pct(st.y, st.t)}%</span></div>
        ${barHtml(st, true)}
      </div>
      <div class="panel"><b>By section</b>
        <ul class="list">${groupsOf(d).map(G => (G.name ? h`<li class="grp-head">${esc(G.name)}</li>` : '') + G.secs.map(s => { const ss = sectionStats(s); return h`<li>
          <div class="sec-row"><span class="name">${esc(sLabel(d, s))}</span><span class="pct">${ss.y}/${ss.t}</span>
            <button class="btn small" data-study-sec="${esc(sKey(s))}" ${ss.y === ss.t ? 'disabled' : ''}>Study ${ss.t - ss.y}</button></div>
          ${barHtml(ss)}</li>`; }).join('')).join('')}</ul>
      </div>
      <div class="panel"><div class="row"><b>Weakest cards</b><div class="spacer"></div>${weakest.length ? h`<button class="btn small primary" data-act="study-weak">Study these ${weakest.length}</button>` : ''}</div>
        ${weakest.length ? h`<ul class="list">${weakest.map(id => { const c = state.cards.get(id); const r = rec(id); return h`<li class="sec-row"><span class="dot ${r.status}"></span><span class="name" style="font-weight:500">${esc(c.prompt)}</span><span class="pct">${r.no}✗ ${r.yes}✓</span></li>`; }).join('')}</ul>` : '<p class="empty">No missed cards yet.</p>'}
      </div>
      <div class="panel"><b>Sessions</b>
        ${sessions.length ? h`<table class="hist"><tr><th>When</th><th>Cards</th><th>First-pass</th><th>Mode</th></tr>
          ${sessions.map(x => h`<tr><td>${fmtDate(x.at)}</td><td>${x.cards}</td><td>${pct(x.yes, x.cards)}% <span style="color:var(--muted)">(${x.yes}/${x.cards})</span></td><td>${x.mode === 'rounds' ? `Rounds ×${x.rounds}` : 'Bring back'}</td></tr>`).join('')}</table>` : '<p class="empty">No sessions yet.</p>'}
      </div>
      <div class="row" style="justify-content:center; margin: 8px 0 20px"><button class="btn danger small" data-act="reset">Reset all progress</button></div>`;
    bindDeckPicker(renderStats);
    const base = () => ({ deck: d.key, order: state.prefs.order, mode: state.prefs.mode });
    $app.querySelectorAll('[data-study-sec]').forEach(b => b.onclick = () => { if (state.session) endSession(true); startSession({ ...base(), sections: [b.dataset.studySec], scope: 'unmastered' }); });
    const w = $app.querySelector('[data-act=study-weak]'); if (w) w.onclick = () => { if (state.session) endSession(true); startSession({ ...base(), sections: d.sections.map(sKey), scope: 'weakest' }); };
    $app.querySelector('[data-act=reset]').onclick = () => { if (confirm('Reset ALL progress and session history on this device? This cannot be undone.')) { state.progress = { cards: {}, sessions: [] }; endSession(false); saveProgress(); renderStats(); toast('Progress reset'); } };
  }

  // ---- browse
  function renderBrowse() {
    const d = deck();
    const q = state.browseQuery.trim().toLowerCase();
    const terms = q.split(/\s+/).filter(Boolean);
    const match = (c) => !terms.length || terms.every(t => (c.prompt + ' ' + stripTags(c.answerHtml) + ' ' + (c.label || '')).toLowerCase().includes(t));
    const hi = (html) => terms.length ? highlight(html, terms) : html;
    let total = 0;
    const secsHtml = d.sections.map(s => {
      const cards = s.cards.filter(match); total += cards.length; if (!cards.length) return '';
      return h`<h2>${s.group ? h`<span class="grp-inline">${esc(s.group)} ›</span> ` : ''}${esc(sLabel(d, s))} <span style="color:var(--muted);font-weight:400">${cards.length}</span></h2><div class="panel" style="padding:4px 16px">
        ${cards.map(c => h`<details class="b-card" ${terms.length ? 'open' : ''}><summary><span class="dot ${statusOf(c.id) || ''}"></span><span class="p">${hi(c.promptHtml || esc(c.prompt))}</span>${c.label ? h`<span class="tag">${esc(c.label)}</span>` : ''}</summary>
          <div class="ans a">${hi(c.answerHtml || '<i>(no answer)</i>')}
            <div class="row" style="margin-top:10px"><button class="btn small" data-mark="no" data-id="${c.id}">Still learning</button><button class="btn small" data-mark="yes" data-id="${c.id}">Got it</button>${statusOf(c.id) ? h`<button class="btn small ghost" data-mark="clear" data-id="${c.id}">Clear</button>` : ''}</div>
          </div></details>`).join('')}</div>`;
    }).join('');
    $app.innerHTML = h`
      <h1>Browse</h1>
      ${state.decks.length > 1 ? h`<div class="panel">${deckPicker()}</div>` : ''}
      <input type="search" id="q" placeholder="Search prompts and answers…" value="${esc(state.browseQuery)}" autocomplete="off">
      <p class="hint">${total} card${total === 1 ? '' : 's'}${terms.length ? ' match' : ''}. Tap a card to expand.</p>
      ${secsHtml || '<p class="empty">Nothing matches.</p>'}`;
    bindDeckPicker(renderBrowse);
    const $q = $app.querySelector('#q');
    let timer; $q.addEventListener('input', () => { clearTimeout(timer); timer = setTimeout(() => { const pos = $q.selectionStart; state.browseQuery = $q.value; renderBrowse(); const nq = $app.querySelector('#q'); nq.focus(); try { nq.setSelectionRange(pos, pos); } catch {} }, 180); });
    $app.querySelectorAll('[data-mark]').forEach(b => b.onclick = (e) => {
      e.preventDefault(); const id = b.dataset.id; const m = b.dataset.mark;
      if (m === 'clear') delete state.progress.cards[id];
      else { const r = rec(id) || { status: null, yes: 0, no: 0, last: 0 }; r.status = m; r[m] += 1; r.last = Date.now(); state.progress.cards[id] = r; }
      saveProgress(); renderBrowse(); toast(m === 'clear' ? 'Cleared' : m === 'yes' ? 'Marked: got it' : 'Marked: still learning');
    });
    $app.querySelectorAll('.ans img').forEach(img => img.onclick = (e) => { e.preventDefault(); openLightbox(img.src); });
  }
  function stripTags(s) { return String(s || '').replace(/<[^>]+>/g, ' ').replace(/&amp;/g, '&').replace(/&lt;/g, '<').replace(/&gt;/g, '>'); }
  function highlight(html, terms) {
    const re = new RegExp('(' + terms.map(t => t.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')).join('|') + ')', 'gi');
    return String(html).split(/(<[^>]+>)/g).map(part => part.startsWith('<') ? part : part.replace(re, '<mark class="hit">$1</mark>')).join('');
  }

  // ---- sync
  async function encodeProgress() {
    const compact = { v: 1, c: {}, s: state.progress.sessions };
    for (const [id, r] of Object.entries(state.progress.cards)) compact.c[id] = [r.status === 'yes' ? 1 : r.status === 'no' ? 2 : 0, r.yes, r.no, r.last];
    const bytes = new TextEncoder().encode(JSON.stringify(compact));
    if (typeof CompressionStream === 'function') {
      try {
        const cs = new CompressionStream('deflate-raw');
        const w = cs.writable.getWriter(); w.write(bytes); w.close();
        const buf = await new Response(cs.readable).arrayBuffer();
        return 'z1.' + b64url(new Uint8Array(buf));
      } catch { /* fall through */ }
    }
    return 'p1.' + b64url(bytes);
  }
  async function decodeProgress(code) {
    code = code.trim();
    const m = code.match(/#sync=([^&\s]+)/); if (m) code = m[1];
    const dot = code.indexOf('.'); const kind = code.slice(0, dot), data = code.slice(dot + 1);
    if (!data || !['z1', 'p1'].includes(kind)) throw new Error('Not a sync code');
    let bytes = unb64url(data);
    if (kind === 'z1') {
      const ds = new DecompressionStream('deflate-raw');
      const w = ds.writable.getWriter(); w.write(bytes); w.close();
      bytes = new Uint8Array(await new Response(ds.readable).arrayBuffer());
    }
    const obj = JSON.parse(new TextDecoder().decode(bytes));
    if (obj.v !== 1) throw new Error('Unknown version');
    const cards = {};
    for (const [id, a] of Object.entries(obj.c || {})) cards[id] = { status: a[0] === 1 ? 'yes' : a[0] === 2 ? 'no' : null, yes: a[1] || 0, no: a[2] || 0, last: a[3] || 0 };
    return { cards, sessions: Array.isArray(obj.s) ? obj.s : [] };
  }
  function b64url(bytes) { let s = ''; for (let i = 0; i < bytes.length; i += 0x8000) s += String.fromCharCode.apply(null, bytes.subarray(i, i + 0x8000)); return btoa(s).replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/, ''); }
  function unb64url(s) { s = s.replace(/-/g, '+').replace(/_/g, '/'); while (s.length % 4) s += '='; const bin = atob(s); const out = new Uint8Array(bin.length); for (let i = 0; i < bin.length; i++) out[i] = bin.charCodeAt(i); return out; }
  function mergeProgress(incoming, replace) {
    if (replace) { state.progress = incoming; }
    else {
      for (const [id, r] of Object.entries(incoming.cards)) {
        const cur = state.progress.cards[id];
        if (!cur) state.progress.cards[id] = r;
        else state.progress.cards[id] = { status: (r.last > cur.last ? r : cur).status, yes: Math.max(cur.yes, r.yes), no: Math.max(cur.no, r.no), last: Math.max(cur.last, r.last) };
      }
      const seen = new Set(state.progress.sessions.map(s => s.at));
      for (const s of incoming.sessions) if (!seen.has(s.at)) state.progress.sessions.push(s);
      state.progress.sessions.sort((a, b) => a.at - b.at);
    }
    saveProgress();
  }
  async function handleIncomingSync(code) {
    history.replaceState(null, '', location.pathname + '#sync');
    state.view = 'sync';
    try {
      const inc = await decodeProgress(code);
      const n = Object.keys(inc.cards).length;
      if (confirm(`Import progress for ${n} cards from the sync link?\n\nOK = merge with this device (keeps the newest answer per card)\nCancel = do nothing`)) { mergeProgress(inc, false); toast('Progress merged'); }
    } catch (e) { toast('That sync link could not be read'); }
    render();
  }
  function renderSync() {
    let y = 0, n = 0; for (const d of state.decks) { const s = deckStats(d); y += s.y; n += s.n; }
    $app.innerHTML = h`
      <h1>Sync devices</h1>
      <p class="sub">Progress is saved in this browser only. To carry it to another device, send yourself the sync link and open it there, or paste the code below.</p>
      <div class="panel">
        <b>This device</b><div class="hint">${y} got it · ${n} still learning · ${state.progress.sessions.length} sessions</div>
        <div class="row" style="margin-top:12px">
          <button class="btn primary" data-act="copy">Copy sync link</button>
          ${navigator.share ? '<button class="btn" data-act="share">Share…</button>' : ''}
          <button class="btn" data-act="show">Show code</button>
        </div>
        <textarea id="out" readonly style="display:none; margin-top:10px" aria-label="Sync code"></textarea>
        <p class="hint">Tip: on Apple devices, copying here and pasting on your iPhone or iPad works through Universal Clipboard. Or text/AirDrop the link to yourself.</p>
      </div>
      <div class="panel">
        <b>Import from another device</b>
        <textarea id="in" placeholder="Paste a sync link or code here" style="margin-top:10px"></textarea>
        <div class="row" style="margin-top:10px">
          <button class="btn primary" data-act="merge">Merge</button>
          <button class="btn" data-act="replace">Replace this device</button>
        </div>
        <p class="hint">Merge keeps the newest answer for each card from either device. Replace overwrites everything here.</p>
      </div>`;
    const $out = $app.querySelector('#out');
    const link = async () => location.origin + location.pathname + '#sync=' + await encodeProgress();
    $app.querySelector('[data-act=copy]').onclick = async () => { const l = await link(); try { await navigator.clipboard.writeText(l); toast('Sync link copied'); } catch { $out.style.display = ''; $out.value = l; $out.select(); toast('Select and copy the text below'); } };
    const sh = $app.querySelector('[data-act=share]'); if (sh) sh.onclick = async () => { const l = await link(); try { await navigator.share({ title: 'Flashcards progress', url: l }); } catch { } };
    $app.querySelector('[data-act=show]').onclick = async () => { $out.style.display = ''; $out.value = await encodeProgress(); };
    const doImport = async (replace) => {
      const v = $app.querySelector('#in').value; if (!v.trim()) { toast('Paste a code first'); return; }
      try { const inc = await decodeProgress(v); if (replace && !confirm('Replace all progress on this device?')) return; mergeProgress(inc, replace); toast(replace ? 'Progress replaced' : 'Progress merged'); renderSync(); }
      catch (e) { toast('Could not read that code'); }
    };
    $app.querySelector('[data-act=merge]').onclick = () => doImport(false);
    $app.querySelector('[data-act=replace]').onclick = () => doImport(true);
  }


  // ------------------------------------------------------------ cheer-up easter egg
  const Cheer = (() => {
    const FALLBACK = { balto: ["Don't worry, Balto believes in you! 💙"], us: ["Don't worry, I believe in you! 💙"] };
    let data = null, loading = null, recentPhotos = [], recentMsgs = [];
    let missStreak = 0, sinceNudge = 0, lastNudgeAt = 0, nudge = null, nudgeTimer = null;

    function load() {
      if (data) return Promise.resolve(data);
      loading = loading || Promise.all([
        fetch('cheer/manifest.json', { cache: 'no-cache' }).then(r => r.ok ? r.json() : { photos: [] }).catch(() => ({ photos: [] })),
        fetch('cheer/messages.json', { cache: 'no-cache' }).then(r => r.ok ? r.json() : FALLBACK).catch(() => FALLBACK),
      ]).then(([m, msgs]) => (data = { photos: m.photos || [], msgs: { ...FALLBACK, ...msgs } }));
      return loading;
    }
    function pick(list, recent, keep) {
      const fresh = list.filter(x => !recent.includes(x));
      const pool = fresh.length ? fresh : list;
      const x = pool[Math.floor(Math.random() * pool.length)];
      recent.push(x); if (recent.length > keep) recent.shift();
      return x;
    }
    function choose() {
      const photo = pick(data.photos, recentPhotos, Math.min(40, Math.max(1, data.photos.length - 1)));
      const list = data.msgs[photo.who] || data.msgs.us;
      return { photo, msg: pick(list, recentMsgs, Math.min(8, list.length - 1)) };
    }
    async function show() {
      await load();
      if (!data.photos.length) { toast('No photos yet 💙'); return; }
      close();
      const { photo, msg } = choose();
      const el = document.createElement('div'); el.className = 'cheer-overlay'; el.id = 'cheer';
      const hearts = Array.from({ length: 9 }, (_, i) => `<span class="cheer-heart" style="left:${6 + i * 11}%; animation-delay:${(i * 0.45).toFixed(2)}s; font-size:${14 + (i * 7) % 16}px">${i % 3 ? '💙' : '🩵'}</span>`).join('');
      el.innerHTML = `<div class="cheer-hearts">${hearts}</div>
        <div class="cheer-card" role="dialog" aria-label="A little encouragement">
          <div class="cheer-frame"><img alt="" src="cheer/${photo.file}"><div class="cheer-spinner">💙</div></div>
          <p class="cheer-msg">${esc(msg)}</p>
          <div class="cheer-actions"><button class="cheer-btn" data-act="another">Another one 💙</button><button class="cheer-btn primary" data-act="close">Back to it ✨</button></div>
        </div>`;
      const img = el.querySelector('img');
      img.onload = () => el.querySelector('.cheer-frame').classList.add('ready');
      img.onerror = () => { el.querySelector('.cheer-frame').classList.add('ready', 'broken'); };
      el.addEventListener('click', (e) => { if (e.target === el) close(); });
      el.querySelector('[data-act=close]').onclick = close;
      el.querySelector('[data-act=another]').onclick = () => show();
      document.body.appendChild(el);
      // warm the cache for the next one
      const nxt = data.photos[Math.floor(Math.random() * data.photos.length)]; if (nxt) { const pre = new Image(); pre.src = 'cheer/' + nxt.file; }
    }
    function close() { const el = document.getElementById('cheer'); if (el) { el.classList.add('closing'); setTimeout(() => el.remove(), 220); } }
    function onAnswer(yes) {
      missStreak = yes ? 0 : missStreak + 1; sinceNudge++;
      if (Date.now() - lastNudgeAt < 4 * 60 * 1000) return;
      if (missStreak >= 3) setNudge('Rough patch? Tap for a smile 💙');
      else if (sinceNudge >= 30) setNudge('Quick smile break? 💙');
    }
    function setNudge(text) {
      lastNudgeAt = Date.now(); missStreak = 0; sinceNudge = 0; nudge = text;
      clearTimeout(nudgeTimer); nudgeTimer = setTimeout(() => { nudge = null; if (state.view === 'study') render(); }, 12000);
    }
    function current() { return nudge; }
    function dismiss() { nudge = null; clearTimeout(nudgeTimer); }
    function pillHtml() { return `<div class="cheer-row"><button class="cheer-pill" data-act="cheer">Feeling discouraged? 💙</button></div>`; }
    function bind(root) { root.querySelectorAll('[data-act=cheer]').forEach(b => b.onclick = (e) => { e.preventDefault(); show(); }); const d = root.querySelector('[data-act=cheer-dismiss]'); if (d) d.onclick = (e) => { e.preventDefault(); dismiss(); render(); }; }
    setTimeout(load, 1500); // fetch quietly after the app is up
    return { show, close, onAnswer, current, pillHtml, bind };
  })();

  // ------------------------------------------------------------ boot
  (async () => {
    try { await loadDecks(); }
    catch (e) { $app.innerHTML = '<p class="empty">Could not load cards.json.<br>Run <code>python3 tools/import_doc.py &lt;doc url&gt;</code> and reload.</p>'; return; }
    if (location.hash.startsWith('#sync=')) { await handleIncomingSync(location.hash.slice(6)); return; }
    const v = (location.hash || '#home').slice(1) || 'home';
    state.view = ['home', 'stats', 'browse', 'sync'].includes(v) ? v : (v === 'study' && state.session ? 'study' : 'home');
    render();
  })();
})();
